	public static function cron_schedules($s){if(!isset($s['gcu_five_minutes'])){$s['gcu_five_minutes']=array('interval'=>300,'display'=>__('Every five minutes (File 14)','global-clinic-usp-integration'));}return $s;}
	public static function activate(){$r=self::install_or_upgrade(true);if(is_wp_error($r)){update_option(self::UPGRADE_ERROR,self::safe_error_record($r),false);update_option('gcu_enabled',0,false);wp_die(esc_html($r->get_error_message()));}self::ensure_future_schema();}
	public static function deactivate(){foreach(array('gcu_daily_governance_check','gcu_process_outbox','gcu_process_inbox','gcu_lifecycle_cleanup')as$h){wp_clear_scheduled_hook($h);}flush_rewrite_rules();}
	public static function maybe_upgrade(){if(GCU_VERSION===(string)get_option(self::VERSION_OPTION,'')&&GCU_SCHEMA_VERSION===(int)get_option(self::SCHEMA_OPTION,0)){self::ensure_future_schema();return true;}$r=self::install_or_upgrade(false);if(is_wp_error($r)){update_option(self::UPGRADE_ERROR,self::safe_error_record($r),false);update_option('gcu_enabled',0,false);return$r;}self::ensure_future_schema();return true;}
	private static function ensure_future_schema(){if(!class_exists('GCU_Future_Intelligence')){return true;}$r=GCU_Future_Intelligence::ensure_schema();if(is_wp_error($r)){update_option(GCU_Future_Intelligence::SAFE_MODE_OPTION,1,false);GCU_Observability::log('error','future_schema_upgrade_deferred',array('code'=>$r->get_error_code()));}return$r;}
	public static function ready_for_runtime(){if(!get_option('gcu_enabled',1)){return new WP_Error('gcu_safe_mode',__('File 14 is in safe mode.','global-clinic-usp-integration'),array('status'=>503));}if(GCU_VERSION!==(string)get_option(self::VERSION_OPTION,'')||GCU_SCHEMA_VERSION!==(int)get_option(self::SCHEMA_OPTION,0)){return new WP_Error('gcu_upgrade_pending',__('File 14 requires a verified schema upgrade before runtime can continue.','global-clinic-usp-integration'),array('status'=>503));}return true;}public static function ready_for_mutation(){return self::ready_for_runtime();}
	private static function install_or_upgrade($activation){if(!self::acquire_lock()){return new WP_Error('gcu_install_locked',__('Global Clinic USP installation or upgrade is already running. Please retry shortly.','global-clinic-usp-integration'));}try{$snap=self::capture_snapshot(true);if(is_wp_error($snap)){return $snap;}$schema=self::schema();if(is_wp_error($schema)){return $schema;}GCU_Capabilities::install();$seed=self::seed_governed_content();if(is_wp_error($seed)){return $seed;}$migration=self::migrate_legacy();if(is_wp_error($migration)){return $migration;}self::schedule();update_option(self::VERSION_OPTION,GCU_VERSION,false);update_option(self::SCHEMA_OPTION,GCU_SCHEMA_VERSION,false);delete_option(self::UPGRADE_ERROR);if($activation){update_option('gcu_enabled',1,false);}flush_rewrite_rules();return true;}finally{self::release_lock();}}
	public static function schema(){global$wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$c=$wpdb->get_charset_collate();$t=self::tables();$e="ENGINE=InnoDB $c";$sql=array();
