	public static function tables(){global$wpdb;return array('claims'=>$wpdb->prefix.'gcu_claims','claim_history'=>$wpdb->prefix.'gcu_claim_history','blocks'=>$wpdb->prefix.'gcu_content_blocks','placements'=>$wpdb->prefix.'gcu_placements','experiments'=>$wpdb->prefix.'gcu_experiments','events'=>$wpdb->prefix.'gcu_conversion_events','audit'=>$wpdb->prefix.'gcu_audit_log','outbox'=>$wpdb->prefix.'gcu_event_outbox','inbox'=>$wpdb->prefix.'gcu_event_inbox','event_tokens'=>$wpdb->prefix.'gcu_event_tokens','rate_limits'=>$wpdb->prefix.'gcu_rate_limits','commands'=>$wpdb->prefix.'gcu_commands');}
	public static function verify_schema(){global$wpdb;$m=array();$w=array();foreach(self::tables()as$k=>$table){$f=$wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$wpdb->esc_like($table)));if($table!==$f){$m[]=$k;continue;}$s=$wpdb->get_row($wpdb->prepare('SHOW TABLE STATUS LIKE %s',$wpdb->esc_like($table)),ARRAY_A);$e=is_array($s)&&isset($s['Engine'])?strtolower((string)$s['Engine']):'';if('innodb'!==$e){$w[$k]=$e?$e:'unknown';}}return($m||$w)?new WP_Error('gcu_schema_verification_failed',__('File 14 database schema could not be verified safely.','global-clinic-usp-integration'),array('missing'=>$m,'non_innodb'=>$w)):true;}
	public static function seed_governed_content(){global$wpdb;$t=self::tables();$now=current_time('mysql',true);foreach(GCU_Policy::canonical_claims()as$key=>$claim){$exists=$wpdb->get_var($wpdb->prepare("SELECT id FROM {$t['claims']} WHERE claim_key=%s",$key));if($exists){continue;}$r=array('public_id'=>wp_generate_uuid4(),'claim_key'=>$key,'claim_text'=>$claim['text'],'basis'=>$claim['basis'],'owner_name'=>$claim['owner'],'source_uri'=>GCU_PLAN_VERSION,'status'=>'active','effective_at'=>gmdate('Y-m-d H:i:s',$claim['effective']),'review_due_at'=>gmdate('Y-m-d H:i:s',$claim['review_due']),'is_public'=>empty($claim['public'])?0:1,'created_by'=>get_current_user_id(),'created_at'=>$now,'updated_at'=>$now);if(false===$wpdb->insert($t['claims'],$r)){return new WP_Error('gcu_seed_claim_failed',__('A canonical claim could not be seeded safely.','global-clinic-usp-integration'));}$h=array('claim_key'=>$key,'row_version'=>1,'status'=>'active','claim_hash'=>hash('sha256',wp_json_encode($r)),'reason'=>'canonical_seed','snapshot'=>wp_json_encode($r),'actor_id'=>get_current_user_id(),'created_at'=>$now);if(false===$wpdb->insert($t['claim_history'],$h)){return new WP_Error('gcu_seed_claim_history_failed',__('Canonical claim history could not be seeded safely.','global-clinic-usp-integration'));}}
