$p=array('global_clinic_patient'=>array('patient_hero','global_clinic','global_clinic_primary','patient',10),'global_clinic_doctor'=>array('doctor_hero','global_clinic','global_clinic_primary','doctor',20),'global_clinic_trust'=>array('trust','global_clinic','global_clinic_trust','all',30),'global_clinic_steps'=>array('how_it_works','global_clinic','global_clinic_steps','all',40),'global_clinic_faq_approval'=>array('faq_approval','global_clinic','global_clinic_faq','all',50),'global_clinic_faq_commission'=>array('faq_commission','global_clinic','global_clinic_faq','all',51),'global_clinic_faq_clinical'=>array('faq_clinical','global_clinic','global_clinic_faq','all',52),'global_clinic_faq_outcome'=>array('faq_outcome','global_clinic','global_clinic_faq','all',53));foreach($p as$key=>$v){$exists=$wpdb->get_var($wpdb->prepare("SELECT id FROM {$t['placements']} WHERE placement_key=%s",$key));if($exists){continue;}$r=array('public_id'=>wp_generate_uuid4(),'placement_key'=>$key,'block_key'=>$v[0],'route_key'=>$v[1],'slot_key'=>$v[2],'audience'=>$v[3],'priority'=>$v[4],'status'=>'active','created_by'=>get_current_user_id(),'created_at'=>$now,'updated_at'=>$now);if(false===$wpdb->insert($t['placements'],$r)){return new WP_Error('gcu_seed_placement_failed',__('A canonical placement could not be seeded safely.','global-clinic-usp-integration'));}}return true;}
	public static function migrate_legacy(){if(get_option('gcu_legacy_migrated',false)){return true;}$l=array('sgc_version'=>get_option('sgc_version',null),'sgc_schema_version'=>get_option('sgc_schema_version',null),'sgc_placements'=>get_option('sgc_placements',null),'sgc_page_map'=>get_option('sgc_page_map',null));$d=array_filter($l,static function($v){return null!==$v;});update_option(self::MIGRATION_LOG,array('detected'=>!empty($d),'legacy_snapshot'=>$d,'action'=>'read-only inventory; no legacy page, option or companion record deleted or overwritten','migrated_at'=>time()),false);update_option('gcu_legacy_migrated',1,false);return true;}
	public static function capture_snapshot($force=false){if(!$force&&get_option(self::SNAPSHOT_OPTION,false)){return true;}global$wpdb;$names=array(self::VERSION_OPTION,self::SCHEMA_OPTION,'gcu_enabled','gcu_settings','gcu_legacy_migrated',self::MIGRATION_LOG);$s=array('captured_at'=>time(),'options'=>array(),'tables'=>array());foreach($names as$n){$sent='__gcu_missing__'.wp_generate_uuid4();$v=get_option($n,$sent);$s['options'][$n]=array('exists'=>$sent!==$v,'value'=>$sent!==$v?$v:null);}$t=self::tables();foreach(array('claims','claim_history','blocks','placements','experiments')as$k){$table=$t[$k];$exists=$wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$wpdb->esc_like($table)));if($table!==$exists){$s['tables'][$k]=array();continue;}$count=(int)$wpdb->get_var("SELECT COUNT(*) FROM `$table`");if($count>self::SNAPSHOT_ROW_MAX){return new WP_Error('gcu_snapshot_too_large',__('File 14 owner data exceeds the bounded rollback snapshot limit.','global-clinic-usp-integration'));}$rows=$wpdb->get_results("SELECT * FROM `$table` ORDER BY id ASC",ARRAY_A);if(null===$rows){return new WP_Error('gcu_snapshot_read_failed',__('File 14 rollback snapshot could not read owner data.','global-clinic-usp-integration'));}$s['tables'][$k]=$rows;}$enc=wp_json_encode($s);if(false===$enc||strlen($enc)>self::SNAPSHOT_MAX){return new WP_Error('gcu_snapshot_size_failed',__('File 14 rollback snapshot exceeds its safe storage bound.','global-clinic-usp-integration'));}$s['snapshot_hash']=hash('sha256',$enc);update_option(self::SNAPSHOT_OPTION,$s,false);return true;}
	public static function rollback_options(){return self::rollback_snapshot();}
	public static function rollback_snapshot(){global$wpdb;$s=get_option(self::SNAPSHOT_OPTION,array());if(empty($s['snapshot_hash'])||!isset($s['options'],$s['tables'])){return new WP_Error('gcu_no_snapshot',__('No verified rollback snapshot is available.','global-clinic-usp-integration'));}$copy=$s;$hash=(string)$copy['snapshot_hash'];unset($copy['snapshot_hash']);$enc=wp_json_encode($copy);if(false===$enc||!hash_equals($hash,hash('sha256',$enc))){return new WP_Error('gcu_snapshot_integrity_failed',__('The File 14 rollback snapshot failed integrity verification.','global-clinic-usp-integration'));}$v=self::verify_schema();if(is_wp_error($v)){return $v;}$t=self::tables();if(false===$wpdb->query('START TRANSACTION')){return new WP_Error('gcu_rollback_transaction_failed',__('Rollback transaction could not start.','global-clinic-usp-integration'));}try{foreach(array('claim_history','claims','blocks','placements','experiments')as$k){$table=$t[$k];if(false===$wpdb->query("DELETE FROM `$table`")){throw new RuntimeException('delete-'.$k);}foreach(isset($s['tables'][$k])&&is_array($s['tables'][$k])?$s['tables'][$k]:array()as$row){if(!is_array($row)||false===$wpdb->insert($table,$row)){throw new RuntimeException('insert-'.$k);}}}if(false===$wpdb->query('COMMIT')){throw new RuntimeException('commit');}}catch(Exception$e){$wpdb->query('ROLLBACK');return new WP_Error('gcu_rollback_write_failed',__('File 14 rollback could not be completed atomically.','global-clinic-usp-integration'));}foreach($s['options']as$n=>$entry){if(empty($entry['exists'])){delete_option($n);}else{update_option($n,$entry['value'],false);}}return true;}
	public static function schedule(){if(!wp_next_scheduled('gcu_daily_governance_check')){wp_schedule_event(time()+HOUR_IN_SECONDS,'daily','gcu_daily_governance_check');}if(!wp_next_scheduled('gcu_process_outbox')){wp_schedule_event(time()+300,'gcu_five_minutes','gcu_process_outbox');}if(!wp_next_scheduled('gcu_process_inbox')){wp_schedule_event(time()+330,'gcu_five_minutes','gcu_process_inbox');}if(!wp_next_scheduled('gcu_lifecycle_cleanup')){wp_schedule_event(time()+HOUR_IN_SECONDS,'hourly','gcu_lifecycle_cleanup');}}
	private static function acquire_lock(){global$wpdb;$name=substr($wpdb->prefix.'gcu-install-upgrade',0,64);$locked=(int)$wpdb->get_var($wpdb->prepare('SELECT GET_LOCK(%s, 1)',$name));if(1!==$locked){return false;}self::$db_lock=$name;update_option(self::LOCK_OPTION,array('acquired_at'=>time(),'request'=>GCU_Policy::trace_id()),false);return true;}
	private static function release_lock(){global$wpdb;if(self::$db_lock){$wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)',self::$db_lock));self::$db_lock=false;}delete_option(self::LOCK_OPTION);}
	private static function safe_error_record(WP_Error$e){return array('code'=>sanitize_key($e->get_error_code()),'occurred_at'=>time(),'version'=>GCU_VERSION,'schema'=>GCU_SCHEMA_VERSION);}
